package com.zajel.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.widget.*;import com.zajel.app.data.*;import com.zajel.app.domain.*;
public final class MainActivity extends Activity {LinearLayout root;EditText email,password;com.zajel.app.core.AppContainer c;public void onCreate(Bundle b){super.onCreate(b);c=((ZajelApplication)getApplication()).container();showAuth();}TextView title(String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(26);v.setTextColor(Color.rgb(24,45,61));v.setPadding(0,0,0,28);return v;}void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(40,70,40,30);root.setBackgroundColor(Color.WHITE);setContentView(root);}void showAuth(){base();root.addView(title("Zajel"));root.addView(new TextView(this){{setText("Sign in to your account");setTextSize(18);}});email=new EditText(this);email.setHint("Email");password=new EditText(this);password.setHint("Password");password.setInputType(129);root.addView(email);root.addView(password);Button in=new Button(this);in.setText("Sign in");Button up=new Button(this);up.setText("Create account");root.addView(in);root.addView(up);TextView status=new TextView(this);root.addView(status);in.setOnClickListener(v->auth(false,status));up.setOnClickListener(v->auth(true,status));}void auth(boolean signup,TextView status){status.setText("Connecting…");AuthRepository.Callback<UserSession> cb=new AuthRepository.Callback<UserSession>(){public void success(UserSession s){runOnUiThread(()->showProfile());}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}};if(signup)c.auth.signUp(email.getText().toString().trim(),password.getText().toString(),cb);else c.auth.signIn(email.getText().toString().trim(),password.getText().toString(),cb);}void showProfile(){base();root.addView(title("Your profile"));EditText user=new EditText(this);user.setHint("Username");EditText name=new EditText(this);name.setHint("Display name");EditText avatar=new EditText(this);avatar.setHint("Avatar URL (optional)");root.addView(user);root.addView(name);root.addView(avatar);Button save=new Button(this);save.setText("Save profile");Button settings=new Button(this);settings.setText("Basic settings");Button out=new Button(this);out.setText("Sign out");root.addView(save);root.addView(settings);root.addView(out);TextView status=new TextView(this);root.addView(status);c.profiles.get(new ProfileRepository.Callback<Profile>(){public void success(Profile p){runOnUiThread(()->{user.setText(p.username);name.setText(p.displayName);avatar.setText(p.avatarUrl);});}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}});save.setOnClickListener(v->c.profiles.update(user.getText().toString(),name.getText().toString(),avatar.getText().toString(),new ProfileRepository.Callback<Profile>(){public void success(Profile p){runOnUiThread(()->status.setText("Profile saved"));}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}}));settings.setOnClickListener(v->showSettings());out.setOnClickListener(v->{c.auth.signOut();showAuth();});}void showSettings(){base();root.addView(title("Settings"));Switch n=new Switch(this);n.setText("Notifications");Switch p=new Switch(this);p.setText("Show online presence");root.addView(n);root.addView(p);Button back=new Button(this);back.setText("Back to profile");root.addView(back);back.setOnClickListener(v->showProfile());}}
